export const meta = {
  name: 'chain-AAAB',
  description: 'RUN-1 stage 1: fix and verify B3+B4 (books.py) and F3 (report.py)',
  phases: [{ title: 'Fix' }, { title: 'Verify' }],
}
const PARKED = { type: 'object', properties: { question: {type:'string'}, header: {type:'string', maxLength: 8},
  options: {type:'array', minItems: 2, maxItems: 4, items: {type:'object', properties: {label:{type:'string'}, does:{type:'string'}, hurts:{type:'string'}}}},
  recommended: {type:'string'}, default: {type:'string'}, reason: {enum: ['taste','fact','conflict']},
  genuine: {type:'boolean'}, gated: {type:'string'}, files: {type:'array', minItems: 1, items: {type:'string'}},
  done: {type:'string'}, stop: {enum: ['none','destructive','security','outside','scope','repro']} },
  required: ['question','header','options','default','reason','genuine','gated','files','stop'] }
const VERDICT = { type: 'object', properties: {
  id: {type: 'string'}, passed: {type: 'boolean'}, why: {type: 'string'},
  evidence: {type: 'string'}, parked: PARKED },
  required: ['id', 'passed', 'why', 'evidence'] }
const M = { cheap: 'sonnet', build: 'opus', deep: 'opus' }
const tier = (t, seat) => M[t[seat]] || (() => { throw Error(`${t.id}: no ${seat} tier`) })()
const results = await pipeline(
  args.items,
  t => agent(t.prompt, { label: `AAAB fix:${t.id}`, phase: 'Fix', model: tier(t, 'fix') }),
  (fix, t) => parallel(t.tickets.map(id => () => agent(
    `Ticket ${id} (part of item ${t.id}). The fix prompt was:\n${t.prompt}\n\nThe fix agent reports:\n${fix}\n\n` +
    `Verify ticket ${id} against the repo yourself: read the diff (git diff, plus untracked files), run \`python -m pytest -q\`, and exercise the behaviour directly. ` +
    `Check the fixer touched only its named files. Default to passed=false if unproven. evidence = the check you ran and its output. ` +
    `If the report says PARKED: check that the independent part works, check (git diff) that the gated files hold no partial guess, judge whether the decision is genuinely the user's, and list every file the gated part would touch; parked.files is the union of yours and the fixer's. Do not edit any file.`,
    { label: `AAAB verify:${id}`, phase: 'Verify', schema: VERDICT, model: tier(t, 'verify') })))
)
return results.flat().filter(Boolean)

